    'tools.highlights.item1.title': 'SysML v2 Modeling (Production)',
    'tools.highlights.item1.description': 'Native SysML v2 support with syntax highlighting, IntelliSense, and real-time validation. Define systems in textual format with LSP features. 18/18 LSP features implemented.',
