    'tools.highlights.item4.description': 'SysML v2 files are plain text—use Git naturally. Branch, merge, PR review workflows just work. No proprietary SCM required.',
    'tools.highlights.item5.title': 'Real-Time Feedback (Production)',
    'tools.highlights.item5.description': 'Instant validation, syntax checking, and error detection. 25+ diagnostic collectors. Markers show exactly where issues are.',
    'tools.highlights.item6.title': 'Multi-Format Support (Experimental)',
    'tools.highlights.item6.description': 'Experimenting with UVL variability, YAML architecture, VSS signals. SysML v2 is production-ready, domain extensions are beta.',
