    'tools.features.item2.title': 'AI Assistant Compatibility (Works with Standard Tools)',
    'tools.features.item2.description': 'No proprietary AI. Works with GitHub Copilot, Claude Code, VS Code AI extensions. Just a language server—AI works naturally.',
