    'about.cta.heading': 'Bereit, Ihr Systems Engineering zu transformieren?',
    'about.cta.subtitle': 'Erfahren Sie, wie SysNex Ihrer Organisation helfen kann, moderne MBSE-Praktiken mit SysML v2 einzuführen.',
