    'hero.kicker': 'Integrierte Mobilitätssysteme',
    'hero.headline': 'Model-Based Systems Engineering,',
    'hero.headline.break': 'neu gedacht',
    'hero.metric': 'Entwickelt für 50M+ VS Code-Entwickler.',
    'hero.paragraph': 'NexSuite macht Systems Engineering so einfach wie Office. Unsere intuitiven Tools und Workflows verwandeln komplexes MBSE in eine alltägliche Aufgabe. Genau wie beim Erstellen eines Dokuments oder einer Tabelle können Sie jetzt Systeme modellieren, Anforderungen nachverfolgen und Compliance sicherstellen—mit derselben Leichtigkeit und Vertrautheit, die Sie von moderner Bürosoftware erwarten.',
