    'hero.insights.aerial.eyebrow': 'Autonomes Fliegen',
    'hero.insights.aerial.title': 'Föderierter Digital Twin für DO-178C',
    'hero.insights.aerial.body': '72 % schnellere Zertifizierungszyklen mit ausführbarem SysML v2, thermischer Lagebeurteilung und Missionsrehearsal-Pipelines.',
    'hero.insights.mobility.eyebrow': 'Vernetzte EV-Plattformen',
    'hero.insights.mobility.title': 'ISO-26262-konformes Software Defined Vehicle',
    'hero.insights.mobility.body': 'Edge-to-Cloud-Orchestrierung, robuste OTA-Updates und git-native Modellnachverfolgung für Ihr Sicherheitskonzept.',
    'hero.insights.infrastructure.eyebrow': 'Mission Ops',
    'hero.insights.infrastructure.title': '24/7 Modell-Observability im Digital Thread',
    'hero.insights.infrastructure.body': 'Ausführbare Spezifikationen speisen Simulation, Code und Testbenches – jede Anomalie wird in Stunden nachverfolgt, bewertet und behoben.',
    'benefits.heading': 'Warum SysNex?',
    'benefits.item1.title': 'Modernes Tooling',
    'benefits.item1.body': 'Nutzen Sie modernste hochperformante Tools, die sich nahtlos in Ihren bestehenden Entwicklungs-Workflow von VS Code bis Git einfügen.',
    'benefits.item2.title': 'Erprobte Methodik',
    'benefits.item2.body': 'Führen Sie SysML v2 mit Sicherheit ein – mit bewährten Methoden vom Requirement bis zur Implementierung.',
    'benefits.item3.title': 'KI-gestützte Insights',
    'benefits.item3.body': 'Erweitern Sie Ihre Modelle mit intelligenter Assistenz für Erstellung, Validierung und Konsistenz komplexer Systeme.',
    'benefits.item4.title': 'Nahtlose Integration',
    'benefits.item4.body': 'Überbrücken Sie die Lücke zwischen Systems Engineering und Softwareentwicklung mit funktionierenden Model-to-Code-Workflows.',
    'benefits.item5.title': 'Zukunftssicher',
    'benefits.item5.body': 'Aufgebaut auf SysML v2 – dem next-gen Standard für moderne Systems-Engineering-Herausforderungen.',
    'benefits.item6.title': 'Entwicklerfreundlich',
    'benefits.item6.body': 'Textuelle Modellierung, LSP-Support und IDE-native Tools, die Entwickler wirklich nutzen möchten.',
    'benefits.item7.title': 'Ready für Functional Safety',
    'benefits.item7.body': 'Integrierte Unterstützung für sicherheitskritische Entwicklung mit Traceability, Gefährdungsanalyse und Compliance-Workflows nach ISO 26262, IEC 61508 und DO-178C.',
    'features.item1.title': '<Tooling/>',
    'features.item1.body': 'Native SysML v2 LSP, textuelle Modellierung, Git-Integration und IDE-native Workflows.',
