    'product.about.heading': 'Über SysNex',
    'product.about.intro': 'SysNex ist ein Tool-Anbieter, der sich auf Enterprise-Grade SysML v2 Language Server Technologie spezialisiert. Wir entwickeln produktionsreife Tools, die Organisationen bei der Einführung moderner Systems-Engineering-Praktiken unterstützen—von textueller Modellierung bis hin zu intelligenter Analyse, mit besonderem Fokus auf funktionale Sicherheit und Compliance.',
    'product.office-suite.heading': 'SysML v2 so einfach wie Microsoft Office',
