    'pricing.faq.heading': 'Häufig gestellte Fragen',
    'pricing.faq.q1': 'Kann ich später den Plan wechseln?',
    'pricing.faq.a1': 'Ja, Sie können Ihren Plan jederzeit upgraden oder downgraden. Änderungen treten sofort in Kraft.',
    'pricing.faq.q2': 'Welche Zahlungsmethoden akzeptieren Sie?',
    'pricing.faq.a2': 'Wir akzeptieren Kreditkarten, Banküberweisungen und Bestellungen für Enterprise-Kunden. Kontaktieren Sie uns für Zahlungsbedingungen und Rabattoptionen.',
    'pricing.faq.q3': 'Gibt es eine kostenlose Testversion?',
    'pricing.faq.a3': 'Ja! Die Essential-Stufe ist dauerhaft kostenlos. Sie können auch eine 30-tägige Testversion jeder kostenpflichtigen Stufe anfordern, um alle Features zu evaluieren.',
    'pricing.faq.q4': 'Bieten Sie Bildungsrabatte?',
    'pricing.faq.a4': 'Ja, wir bieten Bildungsrabatte für Studenten, Fakultäten und akademische Institutionen. Kontaktieren Sie uns mit Ihrer Bildungs-E-Mail-Adresse für Details.',
    'pricing.faq.q5': 'Was ist im Support enthalten?',
    'pricing.faq.a5': 'Essential enthält Community-Support. Standard enthält E-Mail-Support mit 48-Stunden-Antwort. Platform und Automotive enthalten Premium-Support mit 24-Stunden-Antwort und dediziertem Account-Management.',
    'pricing.faq.q6': 'Kann ich dies für kommerzielle Projekte verwenden?',
    'pricing.faq.a6': 'Ja! Alle Stufen können für kommerzielle Projekte verwendet werden. Die Essential-Stufe ist kostenlos für persönliche und kommerzielle Nutzung. Kostenpflichtige Stufen enthalten kommerzielle Lizenzen.',
    'pricing.cta.heading': 'Bereit loszulegen?',
    'pricing.cta.subtitle': 'Starten Sie mit Essential kostenlos, oder kontaktieren Sie uns, um zu besprechen, welcher Plan für Ihr Team richtig ist.',
    'pricing.cta.primary': 'Verkauf kontaktieren',
    'pricing.cta.secondary': 'Features ansehen',
