    // Tools page (German)
    'tools.hero.title': 'Entwicklungstools & Umgebung',
    'tools.hero.description': 'SysNex entwickelt KI-gestützte SysML v2 Tools für VS Code. Unsere Erweiterung integriert sich mit Git und modernen Entwicklungs-Workflows und bringt Systems Engineering in die Developer Experience. Frühstadium-Produkt, nicht unternehmensvalidiert.',
    'tools.highlights.title': 'Hauptfunktionen',
    'tools.highlights.item1.title': 'SysML v2 Modellierung (Produktion)',
    'tools.highlights.item1.description': 'Native SysML v2 Unterstützung mit Syntax-Hervorhebung, IntelliSense und Echtzeit-Validierung. Definieren Sie Systeme im Textformat mit LSP-Features. 18/18 LSP-Features implementiert.',
    'tools.highlights.item2.title': 'KI-Integration (Funktioniert mit Copilot)',
    'tools.highlights.item2.description': 'Kompatibel mit GitHub Copilot, Claude Code und VS Code AI. Funktioniert mit Standard-KI-Assistenten—keine proprietäre KI. Nutzen Sie bestehende Tools, keine benutzerdefinierten Lösungen.',
    'tools.highlights.item3.title': 'Language Server (Produktion)',
    'tools.highlights.item3.description': 'Vollständige SysML v2 Language Server Protocol Implementierung. Unter-50ms Antwortzeit in internen Benchmarks. Autovervollständigung, Diagnostik, Navigation funktionieren alle.',
    'tools.highlights.item4.title': 'Git-Integration (Native)',
    'tools.highlights.item4.description': 'SysML v2 Dateien sind Klartext—nutzen Sie Git natürlich. Branch, Merge, PR-Review-Workflows funktionieren einfach. Kein proprietäres SCM erforderlich.',
    'tools.highlights.item5.title': 'Echtzeit-Feedback (Produktion)',
    'tools.highlights.item5.description': 'Sofortige Validierung, Syntax-Prüfung und Fehlererkennung. 25+ Diagnostik-Sammler. Marker zeigen genau, wo Probleme sind.',
    'tools.highlights.item6.title': 'Multi-Format-Unterstützung (Experimentell)',
    'tools.highlights.item6.description': 'Experimentieren mit UVL-Variabilität, YAML-Architektur, VSS-Signalen. SysML v2 ist produktionsreif, Domain-Erweiterungen sind Beta.',
    'tools.features.title': 'IDE-Funktionen',
    'tools.features.item1.title': 'VS Code Integration (Produktion)',
    'tools.features.item1.description': 'Gebaut als VS Code Erweiterung. Keine benutzerdefinierte IDE—erweitert nur den Editor, den Sie bereits verwenden. Funktioniert überall, wo VS Code funktioniert.',
    'tools.features.item1.item1': 'Native VS Code Erweiterung mit vollständiger LSP-Unterstützung (18/18 Features)',
    'tools.features.item1.item2': 'Syntax-Hervorhebung und Code-Formatierung für SysML v2',
    'tools.features.item1.item3': 'Standard VS Code Datei-Explorer, Suche, Git-Integration',
    'tools.features.item1.item4': 'Multi-Panel-Layout mit VS Code Webviews',
    'tools.features.item1.item5': 'Statusleiste zeigt Diagnostik, Sprachmodus, Kodierung',
    'tools.features.item2.title': 'KI-Assistent-Kompatibilität (Funktioniert mit Standard-Tools)',
    'tools.features.item2.description': 'Keine proprietäre KI. Funktioniert mit GitHub Copilot, Claude Code, VS Code AI Erweiterungen. Nur ein Language Server—KI funktioniert natürlich.',
    'tools.features.item2.item1': 'GitHub Copilot Autovervollständigung für SysML v2 (wenn Sie Copilot haben)',
    'tools.features.item2.item2': 'Claude Code Integration (wenn Sie Claude verwenden)',
    'tools.features.item2.item3': 'Standard LSP bedeutet, dass jedes KI-Tool es verwenden kann',
    'tools.features.item2.item4': 'Kein Vendor Lock-in bei unserer KI—bringen Sie Ihre eigene mit',
    'tools.features.item2.item5': 'Vervollständigungen funktionieren mit oder ohne KI-Unterstützung',
    'tools.features.item3.title': 'SysML v2 Language Server (Produktion)',
    'tools.features.item3.description': 'Vollständige LSP-Implementierung. Unter-50ms Antwort in internen Benchmarks. Alle 18 LSP-Features funktionieren.',
    'tools.features.item3.item1': 'Echtzeit-Syntax-Validierung (25+ Diagnostik-Sammler)',
    'tools.features.item3.item2': 'IntelliSense Autovervollständigung mit ~10K Bibliothekstypen',
    'tools.features.item3.item3': 'Gehe zu Definition, Finde Referenzen, Typ-Hierarchie',
    'tools.features.item3.item4': 'Semantische Hervorhebung (43 Token-Typen, HIR-basiert)',
